import{a as e,c as t,i as n}from"./app-NLbh6JfE.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial.html","title":"【免费无限GPT-4o】AI编程神器Trae详细上手教程","lang":"zh-CN","frontmatter":{"title":"【免费无限GPT-4o】AI编程神器Trae详细上手教程","sidebarGroup":"AI大模型","shortTitle":"【免费无限GPT-4o】AI编程神器Trae详细上手教程","order":1473,"date":"2026-07-22T00:00:00.000Z","category":"面试题","tag":["面试题"],"description":"什么是 Trae？Trae（/treɪ/）与 AI 深度集成，提供智能问答、代码自动补全以及基于 Agent 的 AI 自动编程能力。使用 Trae 开发项目时，你可以与 AI 灵活协作，提升开发效率。需要注意现在 Trae 不能在国内使用","article":false,"head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"WebPage\\",\\"name\\":\\"【免费无限GPT-4o】AI编程神器Trae详细上手教程\\",\\"description\\":\\"什么是 Trae？Trae（/treɪ/）与 AI 深度集成，提供智能问答、代码自动补全以及基于 Agent 的 AI 自动编程能力。使用 Trae 开发项目时，你可以与 AI 灵活协作，提升开发效率。需要注意现在 Trae 不能在国内使用\\"}"],["meta",{"property":"og:url","content":"https://www.code-corey.com/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial.html"}],["meta",{"property":"og:site_name","content":"Corey 知识库"}],["meta",{"property":"og:title","content":"【免费无限GPT-4o】AI编程神器Trae详细上手教程"}],["meta",{"property":"og:description","content":"什么是 Trae？Trae（/treɪ/）与 AI 深度集成，提供智能问答、代码自动补全以及基于 Agent 的 AI 自动编程能力。使用 Trae 开发项目时，你可以与 AI 灵活协作，提升开发效率。需要注意现在 Trae 不能在国内使用"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:image","content":"https://www.code-corey.com/面试题/AI大模型/1473-trae-ai-coding-gpt-4o-tutorial/img-eca11779c258.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-08-09T03:10:04.000Z"}],["meta",{"property":"article:tag","content":"面试题"}],["meta",{"property":"article:published_time","content":"2026-07-22T00:00:00.000Z"}],["meta",{"property":"article:modified_time","content":"2026-08-09T03:10:04.000Z"}]]},"git":{"createdTime":1786240216000,"updatedTime":1786245004000,"contributors":[{"name":"langkemaoxin","username":"langkemaoxin","email":"2363613998@qq.com","commits":3,"url":"https://github.com/langkemaoxin"},{"name":"Cursor","username":"Cursor","email":"cursoragent@cursor.com","commits":3,"url":"https://github.com/Cursor"}]},"readingTime":{"minutes":34.6,"words":10381},"filePathRelative":"面试题/AI大模型/1473-trae-ai-coding-gpt-4o-tutorial.md","excerpt":"<blockquote>\\n<p>来源：<a href=\\"https://www.yuque.com/tulingzhouyu/db22bv/thnro65tussqiu38\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">【免费无限GPT-4o】AI编程神器Trae详细上手教程</a></p>\\n</blockquote>\\n<h1>什么是 Trae？</h1>\\n<p>Trae（/treɪ/）与 AI 深度集成，提供智能问答、代码自动补全以及基于 Agent 的 AI 自动编程能力。使用 Trae 开发项目时，你可以与 AI 灵活协作，提升开发效率。</p>\\n"}`),a={name:`1473-trae-ai-coding-gpt-4o-tutorial.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<blockquote><p>来源：<a href="https://www.yuque.com/tulingzhouyu/db22bv/thnro65tussqiu38" target="_blank" rel="noopener noreferrer">【免费无限GPT-4o】AI编程神器Trae详细上手教程</a></p></blockquote><h1 id="什么是-trae" tabindex="-1"><a class="header-anchor" href="#什么是-trae"><span>什么是 Trae？</span></a></h1><p>Trae（/treɪ/）与 AI 深度集成，提供智能问答、代码自动补全以及基于 Agent 的 AI 自动编程能力。使用 Trae 开发项目时，你可以与 AI 灵活协作，提升开发效率。</p><p><strong>需要注意</strong>现在 Trae 不能在国内使用，但是大家魔法一下就好了</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-eca11779c258.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h1 id="安装-trae-并完成初始设置" tabindex="-1"><a class="header-anchor" href="#安装-trae-并完成初始设置"><span>安装 Trae 并完成初始设置</span></a></h1><h2 id="第一步-安装并启动-trae" tabindex="-1"><a class="header-anchor" href="#第一步-安装并启动-trae"><span>第一步：安装并启动 Trae</span></a></h2><ol><li>前往 <a href="https://www.trae.ai/" target="_blank" rel="noopener noreferrer">Trae 的官网</a>，将 Trae 安装至电脑。</li><li>启动 Trae。</li></ol><p>Trae 首次启动时，你会进入以下页面。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-fc36699c1f39.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>点击 <strong>开始</strong> 按钮。</li></ol><p>Trae 初始配置流程开始。</p><h2 id="第二步-选择主题和语言" tabindex="-1"><a class="header-anchor" href="#第二步-选择主题和语言"><span>第二步：选择主题和语言</span></a></h2><ol><li>选择主题。可选项为 <strong>暗色</strong>、<strong>亮色</strong> 和 <strong>深蓝</strong>。</li><li>选择显示语言。可选项为 <strong>简体中文</strong> 和 <strong>English</strong>。</li></ol><p>若有需要，后续可以在设置中心修改主题和语言。</p><ol><li>点击 <strong>继续</strong> 按钮。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-6a29b9bb2cd8.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h2 id="第三步-从-vs-code-或-cursor-中导入配置" tabindex="-1"><a class="header-anchor" href="#第三步-从-vs-code-或-cursor-中导入配置"><span>第三步：从 VS Code 或 Cursor 中导入配置</span></a></h2><p>若你的电脑中已安装并配置 VS Code 或 Cursor，你可以点击 <strong>从 VS Code 导入</strong> 或 <strong>从 Cursor 导入</strong> 按钮。系统将会从对应的 IDE 中获取插件、IDE 设置、快捷键设置等信息并一键导入到 Trae 中，帮助你快速从其他 IDE 切换到 Trae。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-92995f81ea4b.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h2 id="第四步-添加-trae-相关的命令行" tabindex="-1"><a class="header-anchor" href="#第四步-添加-trae-相关的命令行"><span>第四步：添加 Trae 相关的命令行</span></a></h2><p>添加 Trae 相关的命令行后，你可以在终端中使用命令行更快速地完成 Trae 相关的操作。例如：</p><ul><li>使用 trae 命令快速唤起 Trae。</li><li>使用 trae my-react-app 命令在 Trae 中打开一个项目。</li></ul><p>点击 <strong>安装 <code>trae</code> 命令</strong> 按钮，然后完成授权流程。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-035f92f68496.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h2 id="第五步-登录账号" tabindex="-1"><a class="header-anchor" href="#第五步-登录账号"><span>第五步：登录账号</span></a></h2><p>你需要登录 Trae 以使用 AI 能力。Trae 提供了三种登录方式，分别为 Google 账号登录、Github 账号登录、邮箱登录。若你没有账号，也可以新注册一个账号。</p><p>点击 <strong>登录</strong> 按钮，然后根据页面引导完成登录流程。登录后，你将进入 IDE 界面，如下图所示。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-3aca9f382994.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h2 id="第六步-开始使用-trae" tabindex="-1"><a class="header-anchor" href="#第六步-开始使用-trae"><span>第六步：开始使用 Trae</span></a></h2><p>在 Trae 中，开发你的项目，例如：</p><ul><li>打开已有的项目或克隆 Git 仓库。</li><li>使用 AI 助手从 0 到 1 创建一个新项目。</li></ul><h1 id="管理项目" tabindex="-1"><a class="header-anchor" href="#管理项目"><span>管理项目</span></a></h1><h2 id="什么是-工作空间" tabindex="-1"><a class="header-anchor" href="#什么是-工作空间"><span>什么是 “工作空间”？</span></a></h2><p>“工作空间” 通常为一个在 Trae 中打开的文件夹。若你的项目较为复杂，也可以将多个文件夹添加至一个 “工作空间”。</p><h2 id="创建项目" tabindex="-1"><a class="header-anchor" href="#创建项目"><span>创建项目</span></a></h2><p>Trae 提供三种创建项目的方式：导入本地文件夹、克隆 Git 仓库。</p><h3 id="方式一-导入本地文件夹" tabindex="-1"><a class="header-anchor" href="#方式一-导入本地文件夹"><span>方式一：导入本地文件夹</span></a></h3><ol><li>点击左侧面板中央的 <strong>打开文件夹</strong> 按钮，或在界面左上角点击 <strong>选择项目</strong> &gt; <strong>打开文件夹</strong>。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-6f4112f7259a.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>选择文件夹并在 Trae 中将其打开。</li></ol><p>你将看到以下授权弹窗：</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-c0ba4e61b00f.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li><p>在 <strong>是否信任此文件夹中的文件的作者？</strong> 弹窗中：</p></li><li><p>(可选) 勾选 <strong>信任父文件夹“Downloads”中所有文件的作者</strong>。</p></li></ol><p>此后，在 Trae 中打开任何 “Downloads”（下载） 目录下的文件夹将不再弹出该授权窗口。</p><ol><li>点击 <strong>是，我信任此作者</strong>。</li></ol><p>文件夹已在 IDE 中打开。你可以开始编辑项目。</p><h3 id="方式二-从-github-克隆仓库" tabindex="-1"><a class="header-anchor" href="#方式二-从-github-克隆仓库"><span>方式二：从 GitHub 克隆仓库</span></a></h3><ol><li>点击左侧面板中央的 <strong>克隆 Git 仓库</strong> 按钮，或在界面左上角点击 <strong>选择项目</strong> &gt; <strong>克隆 Git 仓库</strong>。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-2cd330fd0ba2.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>点击 <strong>从 GitHub 克隆</strong>。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-56d0405f7ac4.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><p>你将看到以下授权弹窗。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-caaf9690ad79.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li><p>授权 GitHub 登录 Trae：</p></li><li><p>点击 <strong>允许</strong>。</p></li></ol><p>你将看到以下展示授权码的弹窗：</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-c2461baada91.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>点击 <strong>复制并继续访问 GitHub</strong>。</li></ol><p>已复制授权码，然后你将看到以下弹窗：</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-65571ddd63a3.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>点击 <strong>打开</strong>。</li></ol><p>你将前往 GitHub 上的登录授权页面。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-10a9429cd66e.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li><p>根据页面提示，完成授权。</p></li><li><p>返回 Trae。</p></li></ol><p>弹框中展示可克隆的仓库列表。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-7c34ea263d7b.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>直接从列表中选择一个仓库。</li></ol><p>或</p><p>输入期望克隆的仓库名称，然后点击 <strong>从 GitHub 克隆</strong>。</p><ol><li>在弹窗中，选择该仓库的存储位置，然后点击 <strong>选择为存储库目标</strong>。</li></ol><p>Trae 开始克隆该仓库。克隆完毕后，你会看到以下弹窗。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-6a5ea32fae64.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>按需从以下操作中选择其一：</li></ol><ul><li>点击 <strong>打开</strong>，直接在 Trae 的当前窗口打开该仓库。</li><li>点击 <strong>在新窗口中打开</strong>，在 Trae 中用新窗口中打开该仓库。</li></ul><p>你将看到以下授权弹窗：</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-22f529bf0f8f.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li><p>在 <strong>是否信任此文件夹中的文件的作者？</strong> 弹窗中：</p></li><li><p>(可选) 勾选 <strong>信任父文件夹“Downloads”中所有文件的作者</strong>。</p></li></ol><p>此后，在 Trae 中打开任何 “Downloads”（下载） 目录下的文件夹将不再弹出该授权窗口。</p><ol><li>点击 <strong>是，我信任此作者</strong>。</li></ol><p>仓库已在 IDE 中打开，你可以开始编辑项目。</p><h3 id="方式三-直接从-git-仓库的-url-克隆" tabindex="-1"><a class="header-anchor" href="#方式三-直接从-git-仓库的-url-克隆"><span>方式三：直接从 Git 仓库的 URL 克隆</span></a></h3><p>此方式无需授权 GitHub 登录 Trae，你可以直接使用目标仓库的 URL 来将其克隆至 Trae。</p><ol><li>点击左侧面板中央的 <strong>克隆 Git 仓库</strong> 按钮，或在界面左上角点击 <strong>选择项目</strong> &gt;<strong>克隆 Git 仓库</strong>。</li><li>在 URL 输入框中，输入目标 Git 仓库的 URL，然后点击 <strong>存储库 URL {URL}</strong>。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-579ceceb00b6.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>在弹窗中选择该仓库的存储地址，然后点击 <strong>选择为存储库目标</strong>。</li></ol><p>Trae 开始克隆该仓库。克隆完毕后，你会看到以下弹窗。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-94010ecf154c.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>按需从以下操作中选择其一：</li></ol><ul><li>点击 <strong>打开</strong>，直接在 Trae 的当前窗口打开该仓库。</li><li>点击 <strong>在新窗口打开</strong>，在 Trae 中用新窗口中打开该仓库。</li></ul><p>你将看到以下授权弹窗：</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-af5ed5f7e93e.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li><p>在 <strong>是否信任此文件夹中的文件的作者？</strong> 弹窗中：</p></li><li><p>(可选) 勾选 <strong>信任父文件夹“Downloads”中所有文件的作者</strong>。</p></li></ol><p>此后，在 Trae 中打开任何 “Downloads”（下载） 目录下的文件夹将不弹出该授权窗口。</p><ol><li>点击 <strong>是，我信任此作者</strong>。</li></ol><p>该仓库已在 IDE 中打开。你可以开始编辑项目。</p><h2 id="切换项目" tabindex="-1"><a class="header-anchor" href="#切换项目"><span>切换项目</span></a></h2><p>当 Trae 中存在多个项目时，你可以切换不同的项目进行开发。</p><ol><li>在界面左上角，点击当前项目的名称。 界面上显示如下面板，展示最近导入或使用的项目列表。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-c2ab5a0033c3.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>在 <strong>最近</strong> 列表中，选择需打开的项目。 Trae 打开一个新的窗口，加载并展示该项目。</li></ol><h1 id="管理插件" tabindex="-1"><a class="header-anchor" href="#管理插件"><span>管理插件</span></a></h1><h2 id="安装插件" tabindex="-1"><a class="header-anchor" href="#安装插件"><span>安装插件</span></a></h2><p>你可以从 Trae 或 VS Code 的插件市场安装插件。</p><h3 id="从-trae-的插件市场安装" tabindex="-1"><a class="header-anchor" href="#从-trae-的插件市场安装"><span>从 Trae 的插件市场安装</span></a></h3><ol><li>在左侧导航栏中，点击 <strong>插件市场</strong> 图标。</li></ol><p>界面左侧显示 <strong>插件市场</strong> 面板。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-916366ea4759.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>搜索你想要的插件并在 <strong>未安装</strong> 列表中将其选中。</li></ol><p>界面上显示该插件的详情窗口，展示该插件的详细说明、变更日志等信息。</p><ol><li>点击 <strong>安装</strong>。</li></ol><p>Trae 开始安装该插件。安装完成后，该插件会出现在 <strong>已安装</strong> 列表中。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-a037b7dd1768.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h3 id="从-vs-code-的插件市场安装" tabindex="-1"><a class="header-anchor" href="#从-vs-code-的插件市场安装"><span>从 VS Code 的插件市场安装</span></a></h3><p>如果 Trae 的插件市场未提供你所需的插件，可以将 VS Code 插件市场中的插件安装至 Trae。</p><ol><li>前往 <a href="https://marketplace.visualstudio.com/vscode" target="_blank" rel="noopener noreferrer">VS Code 的插件市场</a>。</li><li>搜索你想要的插件，例如：Pylance。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-b02aaf6c2a58.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>在搜索结果中，点击你所需的插件。</li></ol><p>你会前往该插件的详情页。</p><ol><li>在详情页中，点击 <strong>Version History</strong>。</li><li>结合插件页的 URL 和 Version History 中的信息，提取出以下信息（以 Pylance 为例）：</li></ol><ul><li><p>itemName：URL Query 中的 itemName 字段，如截图中的 ms-python.vscode-pylance，并将小数点（.）前后的内容分成以下两个字段：</p></li><li><p>fieldA：ms-python</p></li><li><p>fieldB：vscode-pylance</p></li><li><p>version：如截图中的 2025.1.102</p></li></ul><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-59dbc4b12ace.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>使用提取出来的 3 个字段的值替换下方 URL 中的同名字段。</li></ol><div class="language-plain line-numbers-mode" data-highlighter="shiki" data-ext="plain" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-plain"><span class="line"><span>模板：</span></span>
<span class="line"><span>https://marketplace.visualstudio.com/_apis/public/gallery/publishers/\${itemName.fieldA}/vsextensions/\${itemName.fieldB}/\${version}/vspackage</span></span>
<span class="line"><span></span></span>
<span class="line"><span>示例：</span></span>
<span class="line"><span>https://marketplace.visualstudio.com/_apis/public/gallery/publishers/ms-python/vsextensions/vscode-pylance/2025.1.102/vspackage</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol><li>在浏览器中输入修改后的 URL，然后按下回车键。</li></ol><p>浏览器开始下载该插件。</p><ol><li>下载完成后，返回 Trae 并打开插件市场。</li><li>将下载的 .vsix 文件拖拽至 <strong>插件市场</strong> 面板中。</li></ol><p>Trae 开始自动安装该插件。安装完成后，该插件会出现在 <strong>已安装</strong> 列表中。</p><h2 id="禁用插件" tabindex="-1"><a class="header-anchor" href="#禁用插件"><span>禁用插件</span></a></h2><ol><li>在 Trae 中，打开插件市场。</li><li>在 <strong>已安装</strong> 列表中，找到需禁用的插件。</li><li>鼠标悬浮至列表中的插件，然后点击 <strong>设置</strong> &gt; <strong>禁用</strong> 或 点击该插件以打开其详情窗口，然后点击 <strong>禁用</strong>。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-752e5cf5d1a1.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h2 id="卸载插件" tabindex="-1"><a class="header-anchor" href="#卸载插件"><span>卸载插件</span></a></h2><ol><li>在 Trae 中，打开插件市场。</li><li>在 <strong>已安装</strong> 列表中，找到需卸载的插件。</li><li>鼠标悬浮至该插件，然后点击 <strong>卸载</strong> 或 点击该插件以打开其详情窗口，然后点击 <strong>卸载</strong>。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-2dc5aea54d64.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h2 id="常见问题" tabindex="-1"><a class="header-anchor" href="#常见问题"><span>常见问题</span></a></h2><h3 id="暂不支持安装-vs-code-插件市场中某个版本的插件" tabindex="-1"><a class="header-anchor" href="#暂不支持安装-vs-code-插件市场中某个版本的插件"><span>暂不支持安装 VS Code 插件市场中某个版本的插件</span></a></h3><p>若 VS Code 插件市场中某个版本的插件依赖了新版 VS Code 中的某些接口，则可能会导致该插件与 Trae 不兼容。你可以查看该插件的 Version History，然后下载该插件的历史版本。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-bcbb2f93fc03.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h1 id="builder-模式-重要" tabindex="-1"><a class="header-anchor" href="#builder-模式-重要"><span>Builder 模式（重要）</span></a></h1><p>Builder 模式可以帮助你从 0 到 1 开发一个完整的项目。你可以将它无缝融入到项目构建的流程中。</p><p>在 Builder 模式下，AI 助手在回答时会根据需求调用不同的工具，包括分析代码文件的工具、编辑代码文件的工具、运行命令的工具等等。从而让回答更精确、更有效。</p><h2 id="系统要求" tabindex="-1"><a class="header-anchor" href="#系统要求"><span>系统要求</span></a></h2><p>对于 Windows 操作系统，须使用 PowerShell 6 或更高版本。安装说明参考<a href="https://learn.microsoft.com/en-us/powershell/scripting/install/installing-powershell-on-windows?view=powershell-7.5" target="_blank" rel="noopener noreferrer">此文档</a>。</p><h2 id="builder-模式的工作流程" tabindex="-1"><a class="header-anchor" href="#builder-模式的工作流程"><span>Builder 模式的工作流程</span></a></h2><p>Builder 模式下，AI 助手会主动读取当前项目中的文件内容，拆解任务并逐步执行，包括：</p><ul><li>提取相关上下文</li><li>创建或修改文件</li><li>生成并运行终端命令</li><li>分析命令运行状态</li></ul><h2 id="启用-builder-模式" tabindex="-1"><a class="header-anchor" href="#启用-builder-模式"><span>启用 Builder 模式</span></a></h2><ol><li>使用快捷键（macOS：Command + U；Windows：Ctrl + U）打开侧边对话框。</li><li>在侧边对话框的左上角，点击 <strong>Builder</strong>。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-67e87e8b23c0.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h2 id="探索-builder-模式" tabindex="-1"><a class="header-anchor" href="#探索-builder-模式"><span>探索 Builder 模式</span></a></h2><p>Builder 提供一系列实用的功能，精准且高效地助力你从 0 到 1 开发项目。</p><h3 id="添加上下文" tabindex="-1"><a class="header-anchor" href="#添加上下文"><span>添加上下文</span></a></h3><p>AI 助手可以理解当前项目中的上下文，包括代码、文件和文件夹，从而更精确地协助你完成开发需求。详情参考《<a href="/docs/context">上下文</a>》。</p><h3 id="输入多模态内容" tabindex="-1"><a class="header-anchor" href="#输入多模态内容"><span>输入多模态内容</span></a></h3><p>你可以在会话中添加图片，例如报错截图、设计稿、参考样式等等，从而更加准确高效地表达需求。详情参考《<a href="/docs/multimodal-input">多模态输入</a>》。</p><h3 id="生成并处理代码变更" tabindex="-1"><a class="header-anchor" href="#生成并处理代码变更"><span>生成并处理代码变更</span></a></h3><p>根据你的需求，AI 助手会自动创建新文件或编辑已有文件，并自动保存生成的代码。你可以选择接受或拒绝代码变更，包括：</p><ul><li><strong>处理多文件内的所有代码变更</strong>：点击输入框上方待审查文件列表中的 <strong>全部接受</strong> 或 <strong>全部拒绝</strong> 按钮，批量接受或拒绝当前项目中的所有代码变更。</li></ul><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-ecb7e698d2f8.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ul><li><strong>处理单文件内的所有代码变更</strong>：在编辑器内打开文件，点击上方提示条中的 <strong>接受</strong> 按钮（快捷键：macOS 为 Command + Enter；Windows 为 Ctrl + Enter）或 <strong>拒绝</strong> 按钮（快捷键：macOS 为 Command + Backspace；Windows 为 Ctrl + Backspace），批量接受或拒绝当前文件内的所有代码变更。</li></ul><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-f91aa6f2c98d.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ul><li><strong>处理单处代码变更</strong>：点击编辑器内某个代码变更右上角的 <strong>^Y</strong> 按钮（快捷键：macOS 为 Control+Y；Windows 为 Alt + Y）或 <strong>^N</strong> 按钮（快捷键：macOS 为 Control + N；Windows 为 Alt + N），接受或拒绝该变更。</li></ul><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-1275a4719b6c.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h3 id="生成并运行命令" tabindex="-1"><a class="header-anchor" href="#生成并运行命令"><span>生成并运行命令</span></a></h3><p>根据你的需求，AI 助手会适时推荐必要的 Shell 命令供你运行（以下图为例）。你可以选择运行或跳过某个命令，AI 助手会根据你的操作完成后续的工作。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-7ff7732f592c.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><p>点击 <strong>运行</strong> 后，终端将运行该命令。命令运行后，AI 助手会自动读取并分析运行结果。如果运行异常，AI 助手会自动分析原因，并给出建议解决方案。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-366363801e65.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><p>若命令运行成功，你可以点击命令卡片右上角的 <strong>终端</strong> 按钮，然后在终端中查看该命令的运行日志。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-75e3b1c3bb3d.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h3 id="预览成果" tabindex="-1"><a class="header-anchor" href="#预览成果"><span>预览成果</span></a></h3><p>AI 助手完成开发需求后，会提供 <strong>预览</strong> 按钮。点击后，Trae 会打开 <strong>Webview</strong> 窗口，用于展示开发成果。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-4cec9b902acd.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><p>预览过程中，若你继续与 AI 助手对话，修改需求，开发成果会在 <strong>Webview</strong> 窗中实时更新。</p><p>在 <strong>Webview</strong> 窗口的右上角，点击 <strong>在浏览器中打开</strong> 按钮，可在浏览器中打开窗口，预览开发成果。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-3c9c3a1b952e.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h3 id="回退版本" tabindex="-1"><a class="header-anchor" href="#回退版本"><span>回退版本</span></a></h3><p>你可以将项目回退到指定会话轮次发起前的版本。</p><ul><li>回退操作不可撤销；</li><li>仅支持在最近活跃的 Builder 窗口中回退版本；</li><li>仅支持回退至最近 10 轮会话内的版本。</li></ul><p>使用以下步骤回退项目的版本：</p><ol><li>找到目标对话气泡。</li><li>点击左侧的 <strong>回退</strong> 按钮。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-258a095c7c2c.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><p>对话框中展示本次回退会影响的文件。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-8c13e3b1dda7.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>点击文件名。</li></ol><p>编辑器内会打开该文件，显示即将发生的变更。</p><ol><li>确认本次回退的影响范围。</li><li>若本次回退符合预期，点击 <strong>确定</strong>。</li></ol><p>Builder 开始回退项目。</p><h3 id="管理历史对话" tabindex="-1"><a class="header-anchor" href="#管理历史对话"><span>管理历史对话</span></a></h3><p>点击 <strong>Builder</strong> 窗口右上角的 <strong>历史会话</strong> 按钮后，左侧会显示 <strong>历史记录</strong> 窗口，展示 Chat 模式和 Builder 模式的所有对话记录。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-5b35397c747d.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ul><li>若你需要查看某轮历史对话，点击该对话条目，你会跳转至该对话的位置。</li><li>若需要删除某轮对话，可以将鼠标悬浮至该对话，然后点击右侧的 <strong>删除</strong> 图标。</li></ul><h1 id="智能问答" tabindex="-1"><a class="header-anchor" href="#智能问答"><span>智能问答</span></a></h1><h2 id="侧边对话-chat-模式" tabindex="-1"><a class="header-anchor" href="#侧边对话-chat-模式"><span>侧边对话（Chat 模式）</span></a></h2><p>侧边对话（Chat 模式）是编码过程中的全能 AI 伙伴，可以用来回答编码问题、讲解代码仓库、生成代码片段、修复错误等。</p><h3 id="打开-chat-模式" tabindex="-1"><a class="header-anchor" href="#打开-chat-模式"><span>打开 Chat 模式</span></a></h3><ol><li>使用快捷键（macOS：Command + U；Windows：Ctrl + U）打开侧边对话框。</li><li>在侧边对话框的左上角，点击 <strong>Chat</strong>。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-9a287a816299.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h3 id="探索-chat-模式" tabindex="-1"><a class="header-anchor" href="#探索-chat-模式"><span>探索 Chat 模式</span></a></h3><h4 id="添加上下文-1" tabindex="-1"><a class="header-anchor" href="#添加上下文-1"><span>添加上下文</span></a></h4><p>AI 助手可以理解当前项目中的上下文，包括代码、文件、文件夹和整个工作空间，从而更精确地协助你完成开发需求。详情参考《<a href="/docs/context">上下文</a>》。</p><h4 id="输入多模态内容-1" tabindex="-1"><a class="header-anchor" href="#输入多模态内容-1"><span>输入多模态内容</span></a></h4><p>你可以在会话中添加图片，例如报错截图、设计稿、参考样式等等，从而更加准确高效地表达需求。详情参考《<a href="/docs/multimodal-input">多模态输入</a>》。</p><h4 id="生成并处理代码变更-1" tabindex="-1"><a class="header-anchor" href="#生成并处理代码变更-1"><span>生成并处理代码变更</span></a></h4><p>Chat 模式下，根据你的需求，AI 助手会自动创建新文件或编辑已有文件并自动保存生成的代码。你可以接受或拒绝变更，包括：</p><p>若你选择接受代码变更，AI 助手会新建文件或将代码变更应用于已有的文件。应用的代码会以 Diff 的形式展示。</p><ul><li><strong>处理多文件内的所有代码变更</strong>：点击输入框上方待审查文件列表中的 <strong>全部接受</strong> 或 <strong>全部拒绝</strong> 按钮，批量接受或拒绝当前项目中的所有代码变更。</li></ul><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-7f3db4204453.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ul><li><strong>处理单文件内的所有代码变更</strong>：在编辑器内打开文件，点击上方提示条中的 <strong>接受</strong> 按钮（快捷键：macOS 为 Command + Enter；Windows 为 Ctrl + Enter）或 <strong>拒绝</strong> 按钮（快捷键：macOS 为 Command + Backspace；Windows 为 Ctrl + Backspace），批量接受或拒绝当前文件内的所有代码变更。</li></ul><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-2c5ab0936e4e.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ul><li><strong>处理单处代码变更</strong>：点击编辑器内某个代码变更右上角的** ^Y** 按钮（快捷键：macOS 为 Control + Y；Windows 为 Alt + Y）或 <strong>^N</strong> 按钮（快捷键：macOS 为 Control + N；Windows 为 Alt + N），接受或拒绝该变更。</li></ul><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-14a04090d823.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><p>此外，对于对话中生成的代码块，你可以进行以下处理：</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-631acf8be946.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><p><strong>编号</strong><br><strong>说明</strong></p><p>1<br> 点击 <strong>复制</strong> 按钮，复制代码块中的全部内容。</p><p>2<br> 在编辑器内的文件中，点击目标区域，然后点击 <strong>插入到光标处</strong> 按钮，将代码块中的内容插入到文件内的光标处。</p><p>3<br> 点击 <strong>添加到新文件</strong> 按钮，新建一个文件，并将代码块中的内容添加至该文件。</p><p>4<br> 若为代码变更，则可以点击 <strong>应用</strong> 按钮，将变更后的代码应用至相应的文件。<br><em><strong>提示</strong></em>：不支持应用和当前工作空间项目无关的代码。</p><h4 id="生成并运行命令-1" tabindex="-1"><a class="header-anchor" href="#生成并运行命令-1"><span>生成并运行命令</span></a></h4><p>Chat 模式下，根据你的需求，AI 助手会提供可一键运行的 Shell 命令。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-f1cb640b3fc3.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><p>你可以按需进行以下操作：</p><p><strong>编号</strong><br><strong>说明</strong></p><p>1<br> 点击 <strong>复制</strong> 按钮，复制该命令。</p><p>2<br> 点击 <strong>添加到终端</strong> 按钮，将命令添加至未被占用的终端。</p><p>3<br> 点击 <strong>运行</strong> 按钮，在未被占用的终端中运行该命令。</p><h4 id="回退版本-1" tabindex="-1"><a class="header-anchor" href="#回退版本-1"><span>回退版本</span></a></h4><p>你可以将项目回退至指定会话轮次发起前的版本。</p><ul><li>回退操作不可撤销；</li><li>仅支持在最近活跃的 Builder 窗口中回退版本；</li><li>仅支持回退至最近 10 轮会话内的版本。</li></ul><ol><li>找到目标对话气泡。</li><li>点击左侧的 <strong>回退</strong> 按钮。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-f8be5d5a854d.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><p>对话框中展示本次回退会影响的文件。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-b9784cfd4ce2.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>点击文件名。</li></ol><p>编辑器内会打开该文件，显示即将发生的变更。</p><ol><li>确认本次回退的影响范围。</li><li>若本次回退符合预期，点击 <strong>确定</strong>。</li></ol><p>AI 助手开始回退项目。</p><h2 id="内嵌对话-重要" tabindex="-1"><a class="header-anchor" href="#内嵌对话-重要"><span>内嵌对话（重要）</span></a></h2><p>Trae 提供了内嵌在代码编辑器中的内嵌对话（Inline Chat）。你能够在编码的过程中随时唤起内嵌对话。使用内嵌对话可以让你在与 AI 助手对话的同时更好地保持编码心流。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-f737073c9405.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h3 id="唤起内嵌对话" tabindex="-1"><a class="header-anchor" href="#唤起内嵌对话"><span>唤起内嵌对话</span></a></h3><p>你可以通过以下两种方式唤起内嵌对话：</p><ul><li>在编辑器内的光标处，使用快捷键（macOS：Command + I；Windows：Ctrl + I）。</li><li>在编辑器内，选中任意代码，然后使用快捷键（macOS：Command + I；Windows：Ctrl + I）或点击悬浮菜单中的 <strong>编辑</strong> 按钮。</li></ul><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-771da4f3bb48.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h3 id="开始问答" tabindex="-1"><a class="header-anchor" href="#开始问答"><span>开始问答</span></a></h3><p>在内嵌对话输入框中输入你的需求，包括为代码添加注释、解释选中的代码、优化选中的代码等等，然后点击右侧的 <strong>发送</strong> 按钮或敲击回车键。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-91a2f2d23016.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h3 id="处理结果" tabindex="-1"><a class="header-anchor" href="#处理结果"><span>处理结果</span></a></h3><p>发送需求后，AI 助手生成的内容将以 Diff 的形式展示在编辑器内。你可以预览变更前后的代码，然后选择采纳或拒绝。</p><ul><li>若你需要接受或拒绝所有内容，点击对话框左下角的 <strong>接受</strong> 按钮（快捷键：macOS 为 Command + Enter；Windows 为 Ctrl + Enter）或 <strong>拒绝</strong> 按钮（快捷键：macOS 为 Command + Backspace；Windows 为 Ctrl + Backspace）按钮。</li><li>若你需要接受或拒绝部分内容，点击内容片段右上角的 <strong>^Y</strong> 按钮（快捷键：macOS 为 Control + Y；Windows 为 Alt + Y）或 <strong>^N</strong> 按钮（快捷键：macOS 为 Control + N；Windows 为 Alt + N）。</li></ul><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-2ac52ffa211b.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h3 id="重试对话" tabindex="-1"><a class="header-anchor" href="#重试对话"><span>重试对话</span></a></h3><p>若 AI 助手生成的内容不符合你的要求，你可以点击对话框左下方的 <strong>重试</strong> 按钮，重新发起一轮同样的对话，让 AI 助手再次尝试回答。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-8c0a6263df23.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h1 id="上下文" tabindex="-1"><a class="header-anchor" href="#上下文"><span>上下文</span></a></h1><p>与 AI 助手对话时，你可以指定 Trae 中的内容（包括代码、文件、文件夹、工作空间）作为上下文供 AI 助手阅读和理解，从而确保 AI 助手的答复更符合你的要求。</p><p>本文介绍指定上下文的三种方式。</p><h2 id="方式一-将编辑器内的内容作为上下文" tabindex="-1"><a class="header-anchor" href="#方式一-将编辑器内的内容作为上下文"><span>方式一：将编辑器内的内容作为上下文</span></a></h2><p>当你的编辑器中存在正在编辑的代码文件时，AI 助手默认能够看到当前文件。你可以直接向 AI 助手提问与当前文件相关的问题。若期望对文件中的某一段代码进行提问，使用以下步骤：</p><ol><li>选中代码。</li><li>点击悬浮菜单中的 <strong>添加到对话</strong> 按钮，将选中的内容作为上下文添加至侧边对话框。</li></ol><p>指定的上下文会显示在侧边对话底部的输入框。以下图为例，输入框内显示所选内容所属的文件名称，以及所选的代码行编号。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-699f740e8d41.webp" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>(可选) 继续添加编辑器中的其他内容片段，或同时添加其他来源的上下文。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-719a00986c1f.webp" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>在上下文旁，输入你的问题，然后发送给 AI 助手。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-2c59e1d68eba.webp" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h2 id="方式二-将终端中的内容作为上下文" tabindex="-1"><a class="header-anchor" href="#方式二-将终端中的内容作为上下文"><span>方式二：将终端中的内容作为上下文</span></a></h2><p>若你希望对终端中的输出内容进行提问（如帮助你修复报错），使用以下步骤：</p><ol><li>在终端中，点击输出内容片段。</li><li>在内容片段区域的右上角，点击 <strong>添加到对话</strong> 按钮，将选中的内容作为上下文添加至侧边对话框。</li></ol><p>指定的上下文会显示在侧边对话底部的输入框。以下图为例，输入框内显示上下文的来源以及行号。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-e89a8f673e23.webp" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>(可选) 继续添加终端中的其他内容片段，或同时添加其他来源的上下文。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-7a8d1b88456f.webp" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>在上下文旁，输入你的问题，然后发送给 AI 助手。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-5216acfabbdb.webp" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h2 id="方式三-使用-键添加上下文" tabindex="-1"><a class="header-anchor" href="#方式三-使用-键添加上下文"><span>方式三：使用 # 键添加上下文</span></a></h2><p>在侧边对话的输入框中，你可以通过 # 符号添加多种类的上下文，包括代码、文件、文件夹和工作区。通常情况下，列表中将展示与编辑器中当前打开文件相关的内容作为推荐的上下文，但你仍然可以自行搜索所需的上下文并将其添加到输入框中。基于你的问题，你可以组合添加各种来源的相关上下文（例如同时添加代码和文件）。</p><h3 id="code" tabindex="-1"><a class="header-anchor" href="#code"><span>#Code</span></a></h3><p>通过 #Code，你可以将函数或类的相关代码作为与 AI 助手对话的上下文。列表中默认展示当前编辑器内打开的文件中的函数或类。选择前，你可以预览列表中推荐的函数或类的相关代码。若推荐的内容非你所需，你可以通过关键词搜索所需的函数或类。</p><p>**若 Trae 中不存在对应语言的 LSP，请提前安装，否则可能导致无法识别代码符号。 **</p><ol><li>在输入框中输入 <strong>#</strong>，或直接点击输入框左下角的 <strong># 引用</strong> 按钮。</li></ol><p>输入框上方显示上下文类型选择列表。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-3631fec05cb5.webp" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>在列表中选择 <strong>Code</strong>（或在 <strong>#</strong> 符号后手动输入 <strong>Code</strong>），然后按下回车键。</li></ol><p>列表将展示编辑器中当前打开的文件中存在的函数和类。将鼠标悬浮在列表中的某个条目后，左侧会展示该函数或类的代码内容，供你预览。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-2f1be047677e.webp" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>若推荐的函数和类非你所需，在 <strong>#Code:</strong> 后输入你想要的函数或类的名称或关键词。</li></ol><p>AI 助手将在项目内搜索相关函数和类，并展示在列表中，你可以进行预览。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-05009f681139.webp" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>从列表中选择需指定为上下文的函数或类。</li><li>在输入框的代码标识后，输入你的问题并发送。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-80312486f8ac.webp" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h3 id="file" tabindex="-1"><a class="header-anchor" href="#file"><span>#File</span></a></h3><p>通过 #File，你可以将指定文件中的所有内容作为与 AI 助手对话的上下文。列表中默认展示近期在编辑器中打开过的文件。你可以预览这些文件所在的目录，以免因存在同名文件而导致错选。若展示的文件非你所需，你可以通过关键词搜索所需文件。</p><ol><li>在输入框中输入 <strong>#</strong>，或直接点击输入框左下角的 <strong># 引用</strong> 按钮。</li></ol><p>输入框上方显示上下文类型选择列表。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-b1e3f7a8d768.webp" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>在列表中选择 <strong>File</strong>（或在 <strong>#</strong> 符号后手动输入 <strong>File</strong>），然后按下回车键。</li></ol><p>列表展示近期在编辑器中打开过的文件。将鼠标悬浮在列表中的某个条目后，左侧会展示该文件所在的目录。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-643c3e16a12c.webp" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>若推荐的文件非你所需，在 <strong>#File:</strong> 后输入你想要的文件的名称或关键词。</li></ol><p>AI 助手将在项目内搜索相关文件并展示在列表中。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-e45d3fd4e180.webp" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>从列表中选择需指定为上下文的文件。</li><li>在输入框的文件标识后，输入你的问题并发送。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-a85f8f9dcb36.webp" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h3 id="folder" tabindex="-1"><a class="header-anchor" href="#folder"><span>#Folder</span></a></h3><p>通过 #Folder，你可以将指定文件夹中的所有内容作为与 AI 助手对话的上下文。列表中默认展示与编辑器中当前所打开文件相关的文件夹。你可以预览这些文件夹所在的目录，以免因存在同名文件夹而导致错选。若展示的文件夹非你所需，你可以通过关键词搜索所需文件夹。</p><ul><li><strong>#Folder 依赖项目代码索引（Project Code Index）是否构建完全。若索引暂未构建完全，可能会影响文件夹内容召回的效果，从而导致 AI 助手的回答不够完整。提问时，若索引从未构建或正在构建中，References 位置将出现 “索引构建中” 或 “索引暂未构建” 的提示，你可以根据引导在设置页管理索引。</strong></li></ul><ol><li>在输入框中输入 <strong>#</strong>，或直接点击输入框左下角的 <strong># 引用</strong> 按钮。</li></ol><p>输入框上方显示上下文类型选择列表。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-ca27d337374c.webp" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>在列表中选择 <strong>Folder</strong>（或在 <strong>#</strong> 符号后手动输入 <strong>Folder</strong>），然后按下回车键。</li></ol><p>列表展示与编辑器中当前所打开文件相关的文件夹。将鼠标悬浮在列表中的某个条目后，左侧会展示该文件夹所在的目录。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-8d1c56614589.webp" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>若推荐的文件夹非你所需，在 <strong>#Folder:</strong> 后输入你想要的文件夹的名称或关键词。</li></ol><p>AI 助手将在项目内搜索相关文件夹并展示在列表中。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-ed6e58b1a7f5.webp" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>从列表中选择需指定为上下文的文件夹。</li><li>在输入框的文件夹标识后，输入你的问题并发送。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-22585f1555dd.webp" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h3 id="workspace" tabindex="-1"><a class="header-anchor" href="#workspace"><span>#Workspace</span></a></h3><p>你可以使用 #Workspace 来向 AI 助手提出有关整个工作空间的问题，AI 助手将自动在工作空间中查找与你的问题最相关的内容作为上下文进行回答。遇到不熟悉的项目时，该功能可以帮助你全局了解该项目所实现的功能和代码，从而使你快速上手该项目的开发。</p><ul><li>**仅支持在 Chat 模式中使用。Builder 模式会自动将整个工作空间作为上下文。 **</li><li><strong>#Workspace 依赖项目代码索引（Project Code Index）是否构建完全。若索引暂未构建完全，可能会影响文件夹内容召回的效果，从而导致 AI 助手的回答不够完整。提问时，若索引从未构建或正在构建中，References 位置将出现 “索引构建中” 或 “索引暂未构建” 的提示，你可以根据引导在设置页管理索引。</strong></li></ul><ol><li>在输入框中输入 <strong>#</strong>，或直接点击输入框左下角的 <strong># 引用</strong> 按钮。</li></ol><p>输入框上方显示上下文类型选择列表。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-1be5d97616c9.webp" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>在列表中选择 <strong>Workspace</strong>（或在 <strong>#</strong> 符号后手动输入 <strong>Workspace</strong>）。</li><li>在输入框的 Workspace 标识后，输入你的问题并发送。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-11fca2338db1.webp" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h1 id="多模态输入" tabindex="-1"><a class="header-anchor" href="#多模态输入"><span>多模态输入</span></a></h1><h2 id="使用方式" tabindex="-1"><a class="header-anchor" href="#使用方式"><span>使用方式</span></a></h2><p>Builder 和 Chat 模式支持多种图片上传方式，包括：</p><ul><li>将图片从外部拖入至对话输入框。</li><li>将图片从当前项目文件树中拖入至对话输入框。</li><li>在对话输入框内粘贴剪贴板中的图片。</li><li>点击输入框左下角的 <strong>图片</strong> 按钮，然后从本地选择图片</li></ul><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-91b71795e0ff.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h1 id="代码自动补全" tabindex="-1"><a class="header-anchor" href="#代码自动补全"><span>代码自动补全</span></a></h1><p>Trae 内置原生的 AI 代码补全功能，无需手动开启。在编辑器内编写代码时，AI 助手会阅读并理解已编写的代码，然后自动续写代码。</p><h2 id="自动补全代码" tabindex="-1"><a class="header-anchor" href="#自动补全代码"><span>自动补全代码</span></a></h2><p>在光标所在位置，敲击回车键换行，AI 助手会阅读并理解当前代码，然后自动补全后续代码。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-6034bb9eb778.gif" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><p>将鼠标悬浮至自动补全的代码区域后，你可以按下 Tab 键，接受所有自动补全的代码，或使用 <strong>Ctrl</strong> + <strong>→</strong> 快捷键，逐字接受代码。</p><h2 id="根据代码注释补全代码" tabindex="-1"><a class="header-anchor" href="#根据代码注释补全代码"><span>根据代码注释补全代码</span></a></h2><p>在对应位置添加注释，然后敲击回车键换行。AI 助手会阅读并理解代码注释，然后生成相关代码。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-03e0148badda.gif" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><p>将鼠标悬浮至自动补全的代码区域后，你可以按下 Tab 键，接受所有自动补全的代码，或使用 <strong>Ctrl</strong> + <strong>→</strong> 快捷键，逐字接受代码。</p><h1 id="源代码管理" tabindex="-1"><a class="header-anchor" href="#源代码管理"><span>源代码管理</span></a></h1><p>在 Trae 中，你可以使用源代码管理功能（Source Control）来管理项目中的代码变更。</p><h2 id="激活源代码管理功能" tabindex="-1"><a class="header-anchor" href="#激活源代码管理功能"><span>激活源代码管理功能</span></a></h2><ol><li>在 Trae 中打开你的项目。</li><li>从左侧的导航栏中，选择 <strong>源代码管理</strong>。</li></ol><p>界面上显示 <strong>源代码管理</strong> 面板。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-ecc90310af26.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>激活源代码管理功能。根据实际需求，从以下方式中选择：</li></ol><ul><li>若当前打开的文件夹中没有 Git 仓库，点击 <strong>初始化仓库</strong> 按钮以初始化一个仓库。</li></ul><p>初始化完成后，该项目便激活了源代码管理功能。</p><ul><li>点击 <strong>发布到 GitHub</strong> 按钮，直接将此文件夹发布到 GitHub 仓库。</li></ul><p>发布完成后，该项目便激活了源代码管理功能。</p><h1 id="ide-设置" tabindex="-1"><a class="header-anchor" href="#ide-设置"><span>IDE 设置</span></a></h1><h2 id="常规设置" tabindex="-1"><a class="header-anchor" href="#常规设置"><span>常规设置</span></a></h2><p>在设置中心，你可以修改通用设置，包括修改主题和语言、从 VS Code 或 Cursor 导入配置、修改编辑器设置和快捷键设置等</p><ol><li>在界面右上角，点击头像。</li><li>在快捷菜单中，选择 <strong>设置</strong>。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-0dec31b1a10f.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><p>Trae 打开 <strong>设置</strong> 窗口，默认展示 <strong>通用</strong> 设置部分。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-5bd443ef0c23.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>在 <strong>通用</strong> 设置部分，按需设置以下内容：</li></ol><ul><li>在 <strong>主题</strong> 处，修改 Trae 的主题。</li><li>在<strong>语言</strong> 处，修改 Trae 的界面语言。</li><li>在 <strong>导入配置</strong> 处，从 VS Code 或 Cursor 导入配置至 Trae。</li><li>在 <strong>Editor 设置</strong> 处，点击 <strong>去设置</strong> 按钮，然后在 <strong>Editor 设置</strong> 窗口中修改编辑器相关设置，包括字体、word-wrap、窗口配置等。</li></ul><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-f33144ebbc97.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ul><li>在 <strong>快捷键设置</strong> 处，点击 <strong>去设置</strong> 按钮，然后在 <strong>键盘快捷键</strong> 窗口中修改快捷键相关设置。</li></ul><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-33b369b8e88d.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h2 id="ai-设置" tabindex="-1"><a class="header-anchor" href="#ai-设置"><span>AI 设置</span></a></h2><h3 id="进入-trae-ai-设置部分" tabindex="-1"><a class="header-anchor" href="#进入-trae-ai-设置部分"><span>进入 Trae AI 设置部分</span></a></h3><ol><li>在界面右上角，点击头像。</li><li>在快捷菜单中，选择 <strong>设置</strong>。</li></ol><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-cf586df68fb1.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><p>Trae 打开 <strong>设置</strong> 窗口。</p><ol><li>从左侧导航栏中，选择 <strong>Trae AI</strong>。</li></ol><p>你已进入 AI 设置部分。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-7ede4f915e77.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h3 id="设置-ai-对话语言" tabindex="-1"><a class="header-anchor" href="#设置-ai-对话语言"><span>设置 AI 对话语言</span></a></h3><p>在 <strong>AI 会话语言</strong> 处，选择 AI 回答时所用的语言。可选项如下：</p><ul><li><strong>Auto 自动</strong>：按用户提问时所用的语言回答。若无法从提问中判断语言，则根据用户历史对话中使用的语言或 Trae 的语言进行回答。</li><li><strong>中文</strong>：若用户未指定语言，则使用中文回答。</li><li><strong>English</strong>：若用户未指定语言，则使用英语回答。</li></ul><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-1c02f81e463f.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h3 id="管理代码索引" tabindex="-1"><a class="header-anchor" href="#管理代码索引"><span>管理代码索引</span></a></h3><p>Trae AI 可以为项目构建索引。构建索引后，用户通过 #Workspace 或 #Folder 方式与 AI 助手对话时，AI 助手能够理解用户当前打开的项目并使用整个项目作为上下文进行回答，从而提供更加精准的回答。</p><p>若未构建索引或索引构建不完全，在使用 #Workspace 或 #Folder 方式与 AI 助手对话时，可能会导致无法召回完整的上下文，进一步导致回答不完整。此时，AI回答处将出现 “索引建构中” 或 “索引暂未建构” 的提示。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-4cd9a6fe8a81.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><p>在 <strong>代码索引管理</strong> 处，你可以管理索引构建的状态和产物。</p><p><strong>操作</strong><br><strong>说明</strong></p><p>开始索引<br> 针对文件数量小于等于 5000 的项目，Trae 将在打开项目时自动构建代码索引。<br> 若项目内的文件数大于 5000 且你期望项目级的回答更准确，此时可以点击 <strong>开始构建</strong> 按钮，为当前项目构建代码索引。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-2788ebe071ce.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><p>停止索引<br> 若代码索引构建过程中出现了异常情况，你期望停止构建，则可以点击 **取消构建 **按钮，本地索引构建将被暂停。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-2636b6595833.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><p>重新构建<br> 若你期望重启构建，则可以点击 **重新构建 **按钮，继续上一次的构建。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-37437c6f1003.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><p>删除索引<br> 若你期望清空代码索引，则可以点击 <strong>清空</strong> 按钮。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-b58a8050d12a.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><h3 id="设置-ai-快捷键" tabindex="-1"><a class="header-anchor" href="#设置-ai-快捷键"><span>设置 AI 快捷键</span></a></h3><p>Trae AI 提供了许多默认快捷键，若与你的个人使用习惯冲突，则可以点击 <strong>快捷键设置</strong> 处的 <strong>去设置</strong> 按钮，然后在 <strong>键盘快捷键</strong> 窗口中修改快捷键。</p><h2 id="快捷键设置" tabindex="-1"><a class="header-anchor" href="#快捷键设置"><span>快捷键设置</span></a></h2><p>通过使用快捷键，你可以提高使用 Trae 的效率。</p><h2 id="常用快捷键" tabindex="-1"><a class="header-anchor" href="#常用快捷键"><span>常用快捷键</span></a></h2><p>此部分罗列 Trae 支持的常用默认快捷键<strong>。</strong></p><h3 id="文本编辑" tabindex="-1"><a class="header-anchor" href="#文本编辑"><span>文本编辑</span></a></h3><p><strong>动作</strong><br><strong>快捷键（macOS）</strong><br><strong>快捷键（Windows）</strong></p><p>Edit a new line<br> Command + Enter<br> Ctrl + Enter</p><p>Copy a line (no need to select)<br> Command + C<br> Ctrl + C</p><p>Cut a line (no need to select)<br> Command + X<br> Ctrl + X</p><p>Paste a line<br> Command + V<br> Ctrl + V</p><p>Select a line (or next line)<br> Command + L<br> Ctrl + L</p><p>Undo action<br> Command + Z<br> Ctrl + Z</p><p>Redo action<br> Command + Shift + Z<br> Ctrl + Shift + Z</p><p>Comment out a line<br> Command + /<br> Ctrl + /</p><p>Invoke search box<br> Command + F<br> Ctrl + F</p><p>Search next item<br> Enter<br> Enter</p><p>Search previous item<br> Shift + Enter<br> Shift + Enter</p><p>Rename symbol<br> F2 or Enter<br> F2</p><p>Go to definition<br> Command + F12<br> Ctrl + F12</p><p>Trigger code auto-completion<br> Ctrl + Space<br> Ctrl + Space</p><h3 id="全局设置" tabindex="-1"><a class="header-anchor" href="#全局设置"><span>全局设置</span></a></h3><p><strong>动作</strong><br><strong>快捷键（macOS）</strong><br><strong>快捷键（Windows）</strong></p><p>Open command palette<br> Command + Shift + P<br> Ctrl + Shift + P</p><p>Open file navigator<br> Command + P<br> Ctrl + P</p><p>Open global search<br> Command + Shift + F<br> Ctrl + Shift + F</p><p>Open settings<br> Command + ,<br> Ctrl + ,</p><h3 id="ai-对话" tabindex="-1"><a class="header-anchor" href="#ai-对话"><span>AI 对话</span></a></h3><p><strong>动作</strong><br><strong>快捷键（macOS）</strong><br><strong>快捷键（Windows）</strong></p><p>Open side AI chat box<br> Command + U<br> Ctrl + U</p><p>Open inline AI chat box<br> Command + I<br> Ctrl + I</p><h2 id="管理快捷键" tabindex="-1"><a class="header-anchor" href="#管理快捷键"><span>管理快捷键</span></a></h2><p>此部分介绍如何管理 Trae 提供的默认快捷键。</p><ol><li>在界面右上角，点击 <strong>头像</strong> &gt; <strong>键盘快捷键</strong>。</li></ol><p>Trae 打开 <strong>键盘快捷键</strong> 窗口。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-f3d6c58bd882.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>在列表中，右击某一快捷键条目。</li></ol><p>界面上显示快捷菜单。</p><figure><img src="/%E9%9D%A2%E8%AF%95%E9%A2%98/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B/1473-trae-ai-coding-gpt-4o-tutorial/img-d74e6b45aac6.png" alt="image" tabindex="0" loading="lazy"><figcaption>image</figcaption></figure><ol><li>根据实际需求，从菜单中选择一个选项，完成对应操作，包括修改快捷键组合、添加快捷键组合、删除快捷键组合等。</li></ol>`,431)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};